namespace {
bool copyFixture(QString source,QString target){QDirIterator it(source,QDir::Files|QDir::NoDotAndDotDot,QDirIterator::Subdirectories);while(it.hasNext()){auto file=it.next(),dest=target+"/"+QDir(source).relativeFilePath(file);if(!QDir().mkpath(QFileInfo(dest).absolutePath())||!QFile::copy(file,dest))return false;}return true;}
QJsonObject screenOf(const QJsonObject& project,QString id){for(auto v:project.value("visual").toObject().value("screens").toArray())if(v.toObject().value("id")==id)return v.toObject();return {};}
bool choose(QListWidget* list,QString id){for(int i=0;i<list->count();++i)if(list->item(i)->data(Qt::UserRole).toJsonObject().value("elementId")==id){list->setCurrentRow(i);return true;}return false;}
QJsonObject readingItem(const QJsonObject& project,QString id){for(auto v:screenOf(project,"title").value("readableLayout").toObject().value("items").toArray())if(v.toObject().value("elementId")==id)return v.toObject();return {};}
}
